import{_ as e,o,c as t,a8 as i}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.06 HTTP 缓存与竞态","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.06-http-cache-and-race.md","filePath":"comics/EP.06-http-cache-and-race.md","lastUpdated":1792817913000}'),l={name:"comics/EP.06-http-cache-and-race.md"};function s(r,a,n,c,d,h){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="ep-06-http-缓存与竞态" tabindex="-1">EP.06 HTTP 缓存与竞态 <a class="header-anchor" href="#ep-06-http-缓存与竞态" aria-label="Permalink to &quot;EP.06 HTTP 缓存与竞态&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../06-network">06-network.md</a>（6.2 缓存策略详解 / 6.5 竞态处理与请求取消）· 示例：<code>examples/06-01-cache-strategy.ts</code>、<code>examples/06-05-chunk-upload.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君的列表每次都全量拉取 2MB，弱网下刷新要等好几秒。</li><li><strong>第 2 格</strong>：码叔揭秘强缓存——<code>Cache-Control: max-age</code> 时长内浏览器直接用本地副本，连请求都不发。</li><li><strong>第 3 格</strong>：像素酱实证协商缓存——带 <code>If-None-Match</code> 问服务器，内容没变返回 304 省流量。</li><li><strong>第 4 格</strong>：码叔结案——缓存之外还有竞态坑：旧响应后到覆盖新结果，要靠取消与序号治理。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-没有缓存的代价" tabindex="-1">第 1 格 · 没有缓存的代价 <a class="header-anchor" href="#第-1-格-·-没有缓存的代价" aria-label="Permalink to &quot;第 1 格 · 没有缓存的代价&quot;">​</a></h3><ul><li>每次进页面都发完整请求，静态资源也全量下载；</li><li>弱网环境下白屏/转圈时间被无限放大，用户直接流失；</li><li>缓存是前端性能优化的第一杠杆：<strong>不发请求永远是最快的</strong>。</li></ul><h3 id="第-2-格-·-强缓存-freshness" tabindex="-1">第 2 格 · 强缓存（Freshness） <a class="header-anchor" href="#第-2-格-·-强缓存-freshness" aria-label="Permalink to &quot;第 2 格 · 强缓存（Freshness）&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> max-age=31536000</span></span></code></pre></div><ul><li>时长内浏览器<strong>完全不发请求</strong>，直接读磁盘/内存副本；</li><li>适合带 hash 指纹的静态资源（<code>app.a3f9.js</code>），内容变文件名就变；</li><li><code>no-cache</code> 不是不缓存，而是&quot;可以缓存但每次要协商验证&quot;。</li></ul><h3 id="第-3-格-·-协商缓存-validation" tabindex="-1">第 3 格 · 协商缓存（Validation） <a class="header-anchor" href="#第-3-格-·-协商缓存-validation" aria-label="Permalink to &quot;第 3 格 · 协商缓存（Validation）&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">If-None-Match</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;abc123&quot;   →   304 Not Modified</span></span></code></pre></div><ul><li>浏览器带上上次的 <code>ETag</code>（内容指纹）问服务器；</li><li>一致 → <code>304</code>，无响应体，省流量；变了 → <code>200</code> 返回新内容；</li><li><code>ETag</code> 按内容生成，比 <code>Last-Modified</code>（秒级时间戳）更精确，一秒内多次修改也能识别。</li></ul><h3 id="第-4-格-·-竞态与缓存陷阱" tabindex="-1">第 4 格 · 竞态与缓存陷阱 <a class="header-anchor" href="#第-4-格-·-竞态与缓存陷阱" aria-label="Permalink to &quot;第 4 格 · 竞态与缓存陷阱&quot;">​</a></h3><ul><li>搜索框快速输入时，先发出的请求可能<strong>后返回</strong>，旧结果覆盖新结果；</li><li>治理三板斧：<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/AbortController" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>AbortController</code></a> 取消上一个、请求序号只认最新、防抖合并输入；</li><li><code>index.html</code> 是所有静态资源入口，一旦强缓存，新版本发布用户永远看不到。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../06-network#_6-9-本章避坑清单">《6.9 本章避坑清单》</a></p></blockquote><ol><li>搜索联想/筛选请求不处理竞态：旧响应后到覆盖新结果，界面显示错误数据；</li><li><code>index.html</code> 设置了长 <code>max-age</code>：发新版后用户仍停留在旧页面，报错找不到新 chunk；</li><li><code>max-age</code> 给得过长且无 hash 指纹：内容更新不及时，只能靠用户强刷。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>强缓存和协商缓存的区别？——<strong>强缓存不发请求直接用本地副本；协商缓存发请求向服务器验证新鲜度，返回 304 或 200</strong>。</li><li><code>no-cache</code> 和 <code>no-store</code> 的区别？——<strong>no-cache 可缓存但每次协商验证；no-store 完全不缓存</strong>。</li><li>搜索输入的竞态怎么治理？——<strong>AbortController 取消上一请求 + 请求序号只渲染最新那次，必要时配合防抖</strong>。</li></ol>',20)])])}const g=e(l,[["render",s]]);export{u as __pageData,g as default};
